import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"Read documents, search the project, and ask questions","description":"Use generated documents, project search, and project-scoped chat to trace analysis results back to source evidence.","frontmatter":{"page_id":"guide-read-search-chat","description":"Use generated documents, project search, and project-scoped chat to trace analysis results back to source evidence."},"headers":[],"relativePath":"en/guide/read-search-chat.md","filePath":"en/guide/read-search-chat.md","lastUpdated":1786290726000}'),n={name:"en/guide/read-search-chat.md"};function s(i,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="read-documents-search-the-project-and-ask-questions" tabindex="-1">Read documents, search the project, and ask questions <a class="header-anchor" href="#read-documents-search-the-project-and-ask-questions" aria-label="Permalink to &quot;Read documents, search the project, and ask questions&quot;">​</a></h1><p>After an analysis, Ershu offers three ways to understand the project. Docs supports structured reading, Search helps locate specific material, and chat on the Docs page can assemble an answer from multiple cited results. They share project permissions but are not the same kind of query.</p><h2 id="confirm-that-the-run-produced-content" tabindex="-1">Confirm that the run produced content <a class="header-anchor" href="#confirm-that-the-run-produced-content" aria-label="Permalink to &quot;Confirm that the run produced content&quot;">​</a></h2><p>Open the latest full-project run from the project&#39;s <strong>Runs</strong> page. Its state should be <code>completed</code> or <code>completed_with_warnings</code>, and its detail should list the documents that were actually produced.</p><p>If the run failed, was cancelled, or produced no documents, address its warnings and Worker errors first. Reloading an empty Docs page cannot create missing content.</p><h2 id="read-generated-documents" tabindex="-1">Read generated documents <a class="header-anchor" href="#read-generated-documents" aria-label="Permalink to &quot;Read generated documents&quot;">​</a></h2><ol><li>Open the project&#39;s <strong>Docs</strong> page.</li><li>Select a document from the left navigation. Documents are grouped by repository and category, so choose the intended repository in a multi-repository project.</li><li>Move through the document with its headings or the on-page table of contents.</li><li>Select a source citation to open its source preview.</li></ol><p>A successful selection shows the complete document in the main area. The active section follows your reading position. A valid citation opens its repository, path, available line numbers, and source excerpt. Citations let you return to evidence; generated prose is not a substitute for checking that evidence.</p><p>Internal document links move between Ershu documents. External links ask for confirmation first. Mermaid diagrams can be opened in a larger view.</p><h2 id="search-the-project" tabindex="-1">Search the project <a class="header-anchor" href="#search-the-project" aria-label="Permalink to &quot;Search the project&quot;">​</a></h2><p>Open the project&#39;s <strong>Search</strong> page, enter a query, and select a mode:</p><ul><li><strong>Keyword</strong> searches by the words you enter and is useful for function names, setting names, and error text.</li><li><strong>Semantic</strong> searches by meaning and requires a usable embedding channel and semantic index.</li><li><strong>Hybrid</strong> combines semantic and keyword results. When semantic capability is unavailable, it can explicitly fall back to keyword results.</li></ul><p>The current page offers one optional repository filter. Search all repositories or select one repository. It does not currently offer branch, language, path, or content-type filters, so do not look for controls described by older material.</p><p>After submitting, a successful result set shows:</p><ul><li>the number of returned items;</li><li>content excerpts;</li><li>result types such as code, documentation, API, README, or configuration;</li><li>source paths and available line numbers; and</li><li>language, document, or section details after expansion when those fields exist.</li></ul><p>Select a result card to expand its full excerpt. The current card does not automatically open Docs or transfer the result into chat.</p><h3 id="understand-search-degradation" tabindex="-1">Understand search degradation <a class="header-anchor" href="#understand-search-degradation" aria-label="Permalink to &quot;Understand search degradation&quot;">​</a></h3><ul><li>Unavailable semantic search must not silently pretend to be keyword search. Check the embedding channel and the run&#39;s search-index status.</li><li>Hybrid search can fall back to keyword results. The page shows a degradation notice when the result did not use full semantic capability.</li><li>When keyword search returns nothing, try a more distinctive symbol, setting name, or error string, and confirm that the repository filter is not excluding the source.</li></ul><h2 id="ask-a-project-scoped-question-from-docs" tabindex="-1">Ask a project-scoped question from Docs <a class="header-anchor" href="#ask-a-project-scoped-question-from-docs" aria-label="Permalink to &quot;Ask a project-scoped question from Docs&quot;">​</a></h2><p>Chat is available from the <strong>Docs</strong> page. Open the chat panel and ask a question that the project&#39;s source or documents can verify, such as, “How does this project load its configuration?”</p><p>The current chat scope is always the whole project:</p><ul><li>it is not limited to the document currently open;</li><li>it is not limited to the current section; and</li><li>in a multi-repository project, an answer can cite more than one repository.</li></ul><p>After sending, the panel adds the user message and progressively fills the response from a stream. A successful answer contains text and any available citations. Select a citation to open the same kind of source preview used by document citations.</p><p>You can also:</p><ul><li>start a new session;</li><li>reopen an existing session;</li><li>search sessions by title; and</li><li>delete a session you no longer need.</li></ul><p>If the answer reports retrieval-only output or no context, first confirm that the project has searchable content, then check the available model channel. Do not treat an answer without traceable project evidence as a verified conclusion.</p><h2 id="choose-the-right-entry-point" tabindex="-1">Choose the right entry point <a class="header-anchor" href="#choose-the-right-entry-point" aria-label="Permalink to &quot;Choose the right entry point&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your question</th><th>Start here</th><th>Evidence of success</th></tr></thead><tbody><tr><td>I want a structured understanding of the project</td><td>Docs</td><td>You find a structured document and can follow citations to source</td></tr><tr><td>I know a function name or error message</td><td>Keyword search</td><td>Results show relevant paths and excerpts</td></tr><tr><td>I know the concept but not the source wording</td><td>Semantic or hybrid search</td><td>Results are relevant and no unresolved degradation notice is shown</td></tr><tr><td>I need to combine multiple sources</td><td>Project chat on Docs</td><td>The answer contains project citations you can open</td></tr></tbody></table><p>If none of the three entry points returns useful content, inspect the run&#39;s documents, index status, and warnings instead of repeatedly submitting the same query.</p>',29)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
